  PERFORM coaching.apply_candidate_exercise_card_v1($card_1_payload${"migrationKey":"725_coaching_drop_squat_stick_candidate_materialization","researchVersion":"2026-07-25.3","definition":{"facilityId":1,"legacyExerciseId":217,"preserveLegacyExerciseId":true,"slug":"drop-squat-to-stick","canonicalName":"Drop Squat to Stick","displayName":"Drop Squat to Stick","aliases":["Drop Squat and Stick","Snap-Down to Stick","Snap Down to Stick","Bilateral Landing Position Drop"],"description":"From a tall bilateral stance, rapidly lower without a preparatory jump into a declared athletic squat/landing position, arrive quietly with both feet grounded, hold the terminal position for the declared duration, then stand and reset. One repetition contains one non-jump drop, one bilateral arrival, one stick, and no rebound, step-off, travel, or takeoff.","familyKey":"bilateral_nonjump_landing_position_acquisition","schemaVersion":"2.0.0","cardVersion":3,"status":"review","identityContract":"tall_bilateral_nonjump_rapid_lowering_to_quiet_bilateral_athletic_squat_terminal_stick_without_rebound_or_takeoff","confidence":{"content":84,"scoring":66,"media":50},"movementPatterns":["squat","land","brace"],"bodyRegions":["foot","ankle","calf","knee","thigh","hip","core"],"requiredEquipment":["none"],"optionalEquipment":["floor_target","video"],"environment":{"surface":"clean, dry, level, stable, non-slip floor with one body-length of clearance","space":"one visible standing station with protected entry and exit","stationCapacity":1,"inspection":["surface, footwear, clearance, footing, visibility, and stop signal","coach sightline to feet, knees, hips, trunk, and terminal hold"],"changeRule":"Changing start, arm action, support, laterality, surface height, rebound, takeoff, cue, hold, dose, symptoms, or substitute requires revalidation."},"population":{"exerciseCardDoesNotClassifyParticipants":true,"readinessIsWorkoutInput":true,"selectionPrerequisites":["pain-free bodyweight squat and stable b